const meses = [
  '', 'janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho',
  'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'
];

const dados = $input.first().json;
const perfil = $('Buscar telefone da proprietária no Supabase').first().json;

const mes_nome = meses[dados.mes] || 'mês';
const saldo = dados.saldo_final;
const entrou = dados.total_entrou;
const saiu = dados.total_saiu;

const nome = perfil[0]?.nome_proprietaria || 'proprietária';
const telefone = perfil[0]?.telefone || '';
const nome_salao = perfil[0]?.nome_salao || 'seu salão';

const emoji_saldo = saldo < 0 ? '🔴' : '🟡';

const mensagem_whatsapp = [
  `Oi ${nome}! 👋 Aqui é o resumo do *${nome_salao}*.`,
  ``,
  `${emoji_saldo} *Resultado de ${mes_nome}/${dados.ano}*`,
  ``,
  `💰 Entrou: *R$ ${entrou.toFixed(2).replace('.', ',')}*`,
  `💸 Saiu:   *R$ ${saiu.toFixed(2).replace('.', ',')}*`,
  `📊 Saldo:  *R$ ${saldo.toFixed(2).replace('.', ',')}*`,
  ``,
  saldo < 0
    ? `Atenção: o salão fechou o mês no negativo. Pode ser hora de revisar os preços dos serviços. 💡`
    : `O salão fechou o mês quase no zero a zero. Que tal avaliar a precificação dos serviços? 💡`,
  ``,
  `_Mensagem automática do app de gestão_`
].join('\n');

const mensagem_email_html = `
<p>Oi <strong>${nome}</strong>,</p>
<p>Aqui está o resumo financeiro de <strong>${mes_nome}/${dados.ano}</strong> do <strong>${nome_salao}</strong>:</p>
<table style="border-collapse:collapse;width:100%;max-width:400px">
  <tr><td style="padding:8px;border-bottom:1px solid #eee">💰 Total entrou</td><td style="padding:8px;border-bottom:1px solid #eee;text-align:right"><strong>R$ ${entrou.toFixed(2).replace('.', ',')}</strong></td></tr>
  <tr><td style="padding:8px;border-bottom:1px solid #eee">💸 Total saiu</td><td style="padding:8px;border-bottom:1px solid #eee;text-align:right"><strong>R$ ${saiu.toFixed(2).replace('.', ',')}</strong></td></tr>
  <tr style="background:#f9f9f9"><td style="padding:8px">📊 Saldo final</td><td style="padding:8px;text-align:right;color:${saldo < 0 ? '#a32d2d' : '#854f0b'}"><strong>R$ ${saldo.toFixed(2).replace('.', ',')}</strong></td></tr>
</table>
<br>
<p>${saldo < 0 ? '⚠️ O salão fechou o mês no negativo.' : '⚠️ O salão fechou o mês quase no zero a zero.'} Pode ser uma boa hora de revisar a precificação dos serviços.</p>
<p style="color:#999;font-size:12px">Mensagem automática do app de gestão</p>
`;

return [{
  json: {
    ...dados,
    nome,
    telefone,
    nome_salao,
    mes_nome,
    mensagem_whatsapp,
    mensagem_email_html
  }
}];
